def _best_seeded_capability(root: Path, task: BuilderTask) -> dict[str, Any] | None:
    best: dict[str, Any] | None = None
    best_score = 0
    for entry in _load_builder_capability_registry(root):
        score = _builder_seed_score(entry, task)
        if score > best_score:
            best = entry
            best_score = score
    return best
